static void dma_callback(void *user_data, int status)
{
	ARG_UNUSED(user_data);

	dma_status = status;

	if (status != 0) {
		LOG_ERR("DMA transfer failed (status %d)", status);
		k_sem_give(&dma_sem);
		return;
	}

	/* Ping-pong: the buffer that was being filled is now done */
	completed_buf = active_buf;
	active_buf = (active_buf == buf_a) ? buf_b : buf_a;

	/* Reload the DMA to start collecting into the next buffer */
	if (dma_start(dma_dev, DMA_SLOT, sensor_src, active_buf, BUF_SIZE) == 0) {
		completed_count++;
	} else {
		LOG_ERR("Failed to reload DMA for next buffer");
	}

	/* Signal the main thread: one buffer is ready to process */
	k_sem_give(&dma_sem);
}

/* Process a completed buffer (runs in main thread context) */
static void process_buffer(const uint8_t *buf)
{
	uint32_t checksum = 0;

	for (size_t i = 0; i < BUF_SIZE; i++) {
		checksum += buf[i];
	}

	LOG_INF("Processed %s: checksum 0x%08x (first bytes: %02x %02x %02x %02x)",
		(buf == buf_a) ? "buf_a" : "buf_b", checksum,
		buf[0], buf[1], buf[2], buf[3]);
}

